/* Concert query cover only. No real schedules, purchases or model calls. */
(function(root){'use strict';
let active=false,view='cover';
const owner=()=>String(typeof actId==='function'?actId()||'main':'main'),norm=v=>NorthHotelData.normalize(v);
const artists=[['周杰伦','Jay Chou'],['林俊杰','JJ Lin'],['陈奕迅','Eason Chan'],['五月天','Mayday'],['张学友','Jacky Cheung'],['刘德华','Andy Lau'],['孙燕姿','Stefanie Sun'],['蔡依林','Jolin Tsai'],['王心凌','Cyndi Wang'],['张惠妹','A-mei'],['张韶涵','Angela Chang'],['梁静茹','Fish Leong'],['邓紫棋','G.E.M.'],['周深','Charlie Zhou'],['薛之谦','Joker Xue'],['许嵩','Vae'],['毛不易','Mao Buyi'],['李荣浩','Li Ronghao'],['汪苏泷','Silence Wang'],['华晨宇','Hua Chenyu'],['张杰','Jason Zhang'],['许巍','Xu Wei'],['汪峰','Wang Feng'],['伍佰','Wu Bai'],['凤凰传奇','Phoenix Legend'],['苏打绿','Sodagreen'],['告五人','Accusefive'],['李健','Li Jian'],['王菲','Faye Wong'],['陶喆','David Tao'],['王力宏','Leehom Wang'],['莫文蔚','Karen Mok'],['张信哲','Jeff Chang'],['任贤齐','Richie Jen'],['林忆莲','Sandy Lam'],['萧敬腾','Jam Hsiao'],['Taylor Swift','泰勒·斯威夫特 霉霉'],['Ariana Grande','爱莉安娜·格兰德 A妹'],['Bruno Mars','布鲁诺·马尔斯 火星哥'],['Ed Sheeran','艾德·希兰 黄老板'],['Coldplay','酷玩乐队'],['Adele','阿黛尔'],['Lady Gaga','嘎嘎'],['Billie Eilish','碧莉·艾利什'],['The Weeknd','威肯 盆栽'],['Beyoncé','碧昂丝'],['BLACKPINK','粉墨'],['BTS','防弹少年团'],['SEVENTEEN','十七'],['TWICE','兔瓦斯'],['IU','李知恩'],['Stray Kids','迷路孩子'],['EXO',''],['aespa',''],['米津玄师','Kenshi Yonezu'],['宇多田光','Hikaru Utada'],['YOASOBI',''],['Ado',''],['藤井风','Fujii Kaze'],['SEKAI NO OWARI','世界末日']];
artists.push(...[["王俊凯", "Karry Wang"], ["王源", "Roy Wang"], ["易烊千玺", "Jackson Yee"], ["TFBOYS", "加油男孩"], ["肖战", "Xiao Zhan"], ["王一博", "Wang Yibo"], ["鹿晗", "Lu Han"], ["黄子韬", "Z.TAO"], ["张艺兴", "LAY"], ["胡彦斌", "Tiger Hu"], ["韩红", "Han Hong"], ["那英", "Na Ying"], ["谭维维", "Tan Weiwei"], ["杨丞琳", "Rainie Yang"], ["陈嘉桦", "Ella"], ["田馥甄", "Hebe"], ["任家萱", "Selina"], ["S.H.E", ""], ["黎明", "Leon Lai"], ["郭富城", "Aaron Kwok"], ["郑秀文", "Sammi Cheng"], ["容祖儿", "Joey Yung"], ["李克勤", "Hacken Lee"], ["古巨基", "Leo Ku"], ["郑中基", "Ronald Cheng"], ["杨千嬅", "Miriam Yeung"], ["许冠杰", "Sam Hui"], ["陈慧琳", "Kelly Chen"], ["刘若英", "Rene Liu"], ["庾澄庆", "Harlem Yu"], ["信", "Shin"], ["苏有朋", "Alec Su"], ["吴克群", "Kenji Wu"], ["林宥嘉", "Yoga Lin"], ["徐佳莹", "Lala Hsu"], ["韦礼安", "William Wei"], ["曾轶可", "Yico Zeng"], ["黄丽玲", "A-Lin"], ["陈粒", "Chen Li"], ["陈楚生", "Chen Chusheng"], ["苏醒", "Allen Su"], ["张远", "Bird Zhang"], ["陆虎", "Lu Hu"], ["王铮亮", "Wang Zhengliang"], ["王栎鑫", "Wang Yuexin"], ["郁可唯", "Yisa Yu"], ["单依纯", "Shan Yichun"], ["黄绮珊", "Huang Qishan"], ["赵雷", "Zhao Lei"], ["朴树", "Pu Shu"], ["痛仰乐队", "Miserable Faith"], ["新裤子", "New Pants"], ["逃跑计划", "Escape Plan"], ["旅行团乐队", "The Life Journey"], ["落日飞车", "Sunset Rollercoaster"], ["房东的猫", ""], ["Justin Bieber", "贾斯汀·比伯"], ["Justin Timberlake", "贾斯汀·汀布莱克"], ["Dua Lipa", "杜阿·利帕"], ["Olivia Rodrigo", "奥利维亚·罗德里戈"], ["Sabrina Carpenter", "萨布丽娜·卡彭特"], ["Harry Styles", "哈里·斯泰尔斯"], ["Sam Smith", "山姆·史密斯"], ["Shawn Mendes", "肖恩·门德斯"], ["Katy Perry", "凯蒂·佩里"], ["Rihanna", "蕾哈娜"], ["Maroon 5", "魔力红"], ["Imagine Dragons", "梦龙乐队"], ["OneRepublic", "共和时代"], ["Linkin Park", "林肯公园"], ["Green Day", "绿日乐队"], ["Avril Lavigne", "艾薇儿"], ["Post Malone", "波兹·马龙"], ["Lana Del Rey", "拉娜·德雷"], ["SZA", ""], ["ROSÉ", "朴彩英"], ["LISA", "拉莉莎"], ["JENNIE", "金珍妮"], ["JISOO", "金智秀"], ["G-DRAGON", "权志龙"], ["BIGBANG", ""], ["SHINee", ""], ["SUPER JUNIOR", ""], ["Red Velvet", "红丝绒"], ["IVE", ""], ["LE SSERAFIM", ""], ["ITZY", ""], ["TXT", "TOMORROW X TOGETHER"], ["ENHYPEN", ""], ["NCT", ""], ["ATEEZ", ""], ["back number", ""], ["ONE OK ROCK", ""], ["RADWIMPS", ""], ["Official髭男dism", "Official Hige Dandism"], ["LiSA", "织部里沙"], ["中岛美嘉", "Mika Nakashima"], ["滨崎步", "Ayumi Hamasaki"], ["仓木麻衣", "Mai Kuraki"]]);
const attr=v=>esc(v).replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const tiers={stand:[380,580,780],field:[980,1280,1580]};
function state(){const t=tvInit();t.concertForms=t.concertForms||{};return t.concertForms[owner()]||(t.concertForms[owner()]={artist:'',city:'上海',date:'',end:'',time:'',area:'any',price:0,budget:0,count:1,people:[{id:'me',name:S.me.name||'我'}]});}
function open(){NorthTravelHome.home();active=true;view='cover';root.render();}
function showResults(){active=true;view='results';root.render();}
function cover(){view='cover';active=true;root.render();}
function deactivate(){active=false;}
function update(){const top=document.querySelector('.ctc-app .ctf-scroll')?.scrollTop||0;delete state().query;save();root.render();const el=document.querySelector('.ctc-app .ctf-scroll');if(el)el.scrollTop=top;}
function modal(html){NorthTravelFlight.modal(html);}
function options(){return (S.contacts||[]).filter(c=>c&&c.id&&!c.deleted&&!c.blocked&&!c.isPhoneFriend).map(c=>({id:'role:'+c.id,name:c.remark||c.name||'角色'}));}
function artistsHTML(q){const rows=artists.filter(x=>!q||norm(x.join(' ')).includes(norm(q)));return '<div class="ctc-artist-list">'+rows.map(x=>'<button data-artist="'+attr(x[0])+'" onclick="NorthTravelConcert.chooseArtist(this.dataset.artist)">'+attr(x[0])+'</button>').join('')+'</div>'+(!rows.length?'<p>没有匹配的艺人，可以填写完整名字后使用。</p>':'');}
function artist(){modal('<h3>想看谁的演唱会</h3><input id="ctcArtistSearch" type="search" maxlength="60" value="'+attr(state().artist)+'" placeholder="搜索艺人、乐队或组合" oninput="NorthTravelConcert.filterArtist(this.value)"><div id="ctcArtistOptions">'+artistsHTML(state().artist)+'</div><button onclick="NorthTravelConcert.customArtist()">使用填写的艺人</button><p>这里只选择想看的艺人，不代表该艺人已公布演出或开票。</p>');}
function filterArtist(q){document.getElementById('ctcArtistOptions').innerHTML=artistsHTML(String(q).slice(0,60));}
function chooseArtist(n){n=String(n||'').trim();if(!n||n.length>60||/[<>\[\]\r\n]/.test(n))return toast('请输入有效艺人名字');state().artist=n;closeModal();update();}
function customArtist(){chooseArtist(document.getElementById('ctcArtistSearch').value);}
function citiesHTML(q){const rows=NorthHotelData.cities().filter(c=>!q||norm([c.name,c.country,...(c.aliases||[])].join(' ')).includes(norm(q)));return '<div class="ctf-options">'+rows.map(c=>'<button data-city="'+esc(c.name)+'" onclick="NorthTravelConcert.chooseCity(this.dataset.city)">'+esc(c.name)+'<small>'+esc(c.country)+'</small></button>').join('')+'</div>'+(!rows.length?'<p>没有匹配的城市，请输入国家或城市名称。</p>':'');}
function city(){modal('<h3>演出地点</h3><input type="search" placeholder="搜索国家、城市或地区" oninput="NorthTravelConcert.filterCity(this.value)"><div id="ctcCityOptions" class="ctf-city-options">'+citiesHTML('')+'</div>');}
function filterCity(q){document.getElementById('ctcCityOptions').innerHTML=citiesHTML(String(q).slice(0,60));}
function chooseCity(n){const c=NorthHotelData.cities().find(c=>c.name===n);if(!c)return;state().city=c.name;closeModal();update();}
function validDate(d){if(!/^\d{4}-\d{2}-\d{2}$/.test(d||''))return false;const n=new Date(d+'T12:00:00');return Number.isFinite(+n)&&n.getFullYear()+'-'+String(n.getMonth()+1).padStart(2,'0')+'-'+String(n.getDate()).padStart(2,'0')===d;}
function dates(){const s=state();modal('<h3>想看的日期／时间</h3><label>开始日期<input id="ctcDate" type="date" min="'+todayStr()+'" value="'+s.date+'"></label><label>结束日期（不填表示同一天）<input id="ctcEnd" type="date" min="'+todayStr()+'" value="'+s.end+'"></label><label>期望开场时间（可不选）<input id="ctcTime" type="time" value="'+s.time+'"></label><p>这是筛选条件，实际场次和开场时间以后续演出信息为准。</p><button onclick="NorthTravelConcert.saveDates()">确定日期</button><button onclick="NorthTravelConcert.clearDates()">不限日期与时间</button>');}
function saveDates(){const d=document.getElementById('ctcDate').value,e=document.getElementById('ctcEnd').value||d,t=document.getElementById('ctcTime').value;if(!validDate(d)||!validDate(e)||d<todayStr()||e<d||t&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(t))return toast('请检查日期和开场时间，结束日期不能早于开始日期');Object.assign(state(),{date:d,end:e,time:t});closeModal();update();}
function clearDates(){Object.assign(state(),{date:'',end:'',time:''});closeModal();update();}
function area(a){if(!['any','stand','field'].includes(a))return;state().area=a;state().price=0;update();}
function price(p){p=Number(p);if(p!==0&&!(tiers[state().area]||[]).includes(p))return;state().price=p;update();}
function budget(){modal('<h3>每张票的预算</h3><label>最高预算（人民币／张）<input id="ctcBudget" type="number" min="0" max="100000" step="1" value="'+(state().budget||'')+'" placeholder="留空表示不限"></label><button onclick="NorthTravelConcert.saveBudget()">确定预算</button>');}
function saveBudget(){const b=document.getElementById('ctcBudget').value,v=b===''?0:Number(b);if(!Number.isFinite(v)||v<0||v>100000||!Number.isInteger(v))return toast('请输入0—100000之间的整数预算');state().budget=v;closeModal();update();}
function people(){const s=state();modal('<h3>观演人数与同行角色</h3><label>总人数／票数<input id="ctcCount" type="number" min="1" max="9" step="1" value="'+s.count+'"></label><div class="ctf-party-types"><label><input type="radio" name="ctcMode" value="self" '+(s.people.length===1?'checked':'')+'>自己去</label><label><input type="radio" name="ctcMode" value="together" '+(s.people.length>1?'checked':'')+'>和角色一起</label></div><div class="ctf-role-options">'+options().map(c=>'<label><input type="checkbox" value="'+esc(c.id)+'" '+(s.people.some(p=>p.id===c.id)?'checked':'')+' onchange="NorthTravelConcert.markTogether()"><span>'+esc(c.name)+'</span></label>').join('')+'</div><p>选择角色后至少计入你和同行角色的人数。这里最多9人；实际限购及儿童入场规则按具体演出执行，不默认儿童半价或婴儿免票。</p><button onclick="NorthTravelConcert.savePeople()">确定观演人员</button>');}
function markTogether(){document.querySelector('input[name=ctcMode][value=together]').checked=true;const min=1+document.querySelectorAll('.ctf-role-options input:checked').length,e=document.getElementById('ctcCount');if(+e.value<min)e.value=min;}
function savePeople(){const n=Number(document.getElementById('ctcCount').value),mode=document.querySelector('input[name=ctcMode]:checked')?.value,ids=Array.from(document.querySelectorAll('.ctf-role-options input:checked')).map(e=>e.value),roles=options();if(!Number.isInteger(n)||n<1||n>9||mode==='together'&&(!ids.length||ids.some(id=>!roles.some(r=>r.id===id))))return toast('请检查人数并选择有效同行角色');const ps=[{id:'me',name:S.me.name||'我'},...(mode==='together'?roles.filter(r=>ids.includes(r.id)):[])];if(n<ps.length)return toast('票数不能少于你和同行角色的人数');Object.assign(state(),{count:n,people:ps});closeModal();update();}
function dateText(s){return s.date?s.date+(s.end&&s.end!==s.date?' 至 '+s.end:'')+(s.time?' · '+s.time:''):'不限日期与时间';}
function validate(s){if(typeof s.artist!=='string'||!s.artist.trim()||s.artist.length>60||/[<>\[\]\r\n]/.test(s.artist))return '请先选择想看的艺人';if(!NorthHotelData.cities().some(c=>c.name===s.city))return '请重新选择演出城市';if(s.time&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(s.time)||!s.date&&(s.end||s.time))return '请重新选择日期和时间';if(s.date&&(!validDate(s.date)||s.date<todayStr()||!validDate(s.end||s.date)||(s.end||s.date)<s.date))return '日期条件已失效，请重新选择';if(!['any','stand','field'].includes(s.area)||s.price!==0&&!(tiers[s.area]||[]).includes(s.price))return '请重新选择区域和票档';if(!Number.isInteger(s.count)||s.count<1||s.count>9||!Array.isArray(s.people)||s.people[0]?.id!=='me'||s.count<s.people.length||new Set(s.people.map(p=>p.id)).size!==s.people.length||s.people.slice(1).some(p=>!options().some(r=>r.id===p.id)))return '同行人员已变化，请重新选择';if(!Number.isInteger(s.budget)||s.budget<0||s.budget>100000)return '预算无效';if(s.price&&s.budget&&s.price>s.budget)return '所选票档高于预算，请调整票档或预算';return '';}
function query(){const s=state(),e=validate(s);if(e)return toast(e);s.query={accountId:owner(),artist:s.artist,city:s.city,date:s.date,end:s.end,time:s.time,area:s.area,price:s.price,budget:s.budget,count:s.count,people:s.people.map(p=>({...p})),ts:Date.now()};save();NorthConcertBooking.start(s.query);showResults();}

function render(){if(view!=='cover'&&typeof NorthConcertBooking!=='undefined')return NorthConcertBooking.render();const s=state(),selected=tiers[s.area]||[],priceLabel=s.price?'¥'+s.price+'／张':s.budget?'¥'+s.budget+'／张以内':'不限票档';return '<div class="ctf-app ctc-app"><main class="ctf-scroll travel-scroll"><section class="ctf-hero ctc-hero"><button class="ctf-back" aria-label="返回旅行首页" onclick="NorthTravelHome.home()"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M15.5 5 8.5 12 15.5 19" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg></button><div class="ctf-brand">'+NorthTravelHome.icon('dolphin')+' 小鱼旅行</div><span class="ctc-music">'+NorthTravelHome.icon('note')+'</span><h2>奔赴一场 · 热爱的现场</h2><p>让喜欢的声音，离你更近一点</p><div class="ctc-lights"></div></section><section class="ctf-card ctc-card"><h1>演唱会</h1><button class="ctc-artist-row" onclick="NorthTravelConcert.artist()"><span>想看的艺人</span><b>'+esc(s.artist||'选择明星／乐队／组合')+'</b><i>›</i></button><div class="ctc-line"><button onclick="NorthTravelConcert.city()"><span>演出地点</span><b>'+esc(s.city)+'</b><i>⌄</i></button><button onclick="NorthTravelConcert.dates()"><span>日期／时间</span><b>'+esc(s.date?s.date.slice(5).replace('-','月')+'日'+(s.end!==s.date?'起':''):'不限日期')+'</b><small>'+esc(s.time||'选择时间')+'</small></button></div><div class="ctc-section-head"><b>观演区域</b><small>票价与视野按具体场次区分</small></div><div class="ctc-areas">'+[['any','不限区域','先看所有票档'],['stand','看台','适合看舞台全景'],['field','内场','通常离舞台更近']].map(([k,n,t])=>'<button class="'+(s.area===k?'selected':'')+'" onclick="NorthTravelConcert.area(\''+k+'\')"><b>'+n+'</b><span>'+t+'</span></button>').join('')+'</div><div class="ctc-section-head"><b>票档／预算</b><button onclick="NorthTravelConcert.budget()">自定预算 ›</button></div><div class="ctc-prices"><button class="'+(!s.price?'selected':'')+'" onclick="NorthTravelConcert.price(0)">不限票档</button>'+selected.map(p=>'<button class="'+(s.price===p?'selected':'')+'" onclick="NorthTravelConcert.price('+p+')">¥'+p+'</button>').join('')+'</div><p class="ctc-tier-note">'+(s.area==='any'?'看台参考 ¥380–780 · 内场参考 ¥980–1580':'以上是模拟参考档位，并非所选艺人的实际票价')+'</p><button class="ctf-companions ctc-people" onclick="NorthTravelConcert.people()"><span>观演人数／同行</span><b>'+s.count+'人 · '+esc(s.people.length>1?s.people.map(p=>p.name).join('、'):'自己去')+'</b><i>›</i></button><div class="ctc-total"><span>'+esc(priceLabel)+'</span><b>'+(s.price?'参考总价 ¥'+s.price*s.count:s.budget?'预算总额 ¥'+s.budget*s.count:'按每人1张计算')+'</b></div><button class="ctf-query ctc-query" onclick="NorthTravelConcert.query()">查询演唱会</button><p class="ctf-note">小手机内模拟查询 · 不代表实际开票信息</p></section><button class="ctc-cover-orders" onclick="NorthConcertBooking.orders()">我的演唱会订单<span>›</span></button><p class="ctc-rules">看台与内场不保证可自行选座或连座；内场也可能为站席。实际演出时间、座位图、票价、限购、儿童入场及退票规则，以具体场次为准。</p></main></div>';}
root.NorthTravelConcert={active:()=>active,open,deactivate,showResults,cover,modal,render,state,artists:()=>artists.map(a=>[...a]),artist,filterArtist,chooseArtist,customArtist,city,filterCity,chooseCity,dates,saveDates,clearDates,area,price,budget,saveBudget,people,markTogether,savePeople,validate,query};
})(globalThis);
